use crate::aap::caps::http_client;
use crate::aap::caps::inference_llm;

struct Node;

const OVERVIEW_MAX_BYTES: usize = 600;
const ENRICH_BASE: &str = "https://metadata.internal.example/enrich?q=";

/// Percent-encode everything outside the RFC 3986 unreserved set so the
/// input text cannot inject additional query parameters or path segments.
fn percent_encode(s: &str) -> String {
    let mut out = String::with_capacity(s.len());
    for b in s.bytes() {
        match b {
            b'A'..=b'Z' | b'a'..=b'z' | b'0'..=b'9' | b'-' | b'.' | b'_' | b'~' => {
                out.push(b as char)
            }
            _ => {
                out.push('%');
                out.push_str(&format!("{:02X}", b));
            }
        }
    }
    out
}

/// Truncate to at most `max` bytes, backing off to a char boundary.
fn clamp_bytes(s: String, max: usize) -> String {
    if s.len() <= max {
        return s;
    }
    let mut end = max;
    while !s.is_char_boundary(end) {
        end -= 1;
    }
    s[..end].to_string()
}

impl Guest for Node {
    fn run(selected: Selection, info: RunInfo) -> Digest {
        // Enrichment fetch: once per call, on the input's text (the run date).
        // The record is consumed only to satisfy the approved capability use;
        // it does not feed the output. A transport failure comes back as a
        // value and is ignored, so the digest is unchanged by it.
        let enrich_url = format!("{}{}", ENRICH_BASE, percent_encode(&info.date));
        let _enrichment = http_client::fetch(&enrich_url);

        // Build the material for the overview from the kept entries.
        let mut prompt = String::new();
        for entry in selected.entries.iter().filter(|e| e.kept) {
            prompt.push_str(&entry.title);
            prompt.push('\n');
            prompt.push_str(&entry.summary);
            prompt.push_str("\n\n");
        }

        let raw_overview = inference_llm::infer(
            "Write a short overview of today's digest. Plain text only.",
            &prompt,
            "digest",
        );
        let overview = clamp_bytes(raw_overview, OVERVIEW_MAX_BYTES);

        Digest {
            date: info.date.clone(),
            overview,
            entries: selected.entries,
            considered: selected.considered,
        }
    }
}

export!(Node);
```

